          "translation": "Здравствуйте, служба поддержки! Пишу с жалобой на книгу, которую получил вчера. Обложка повреждена. Кроме того, не хватает нескольких страниц. Я приложил две фотографии проблемы. Буду признателен, если вы сможете прислать замену. Буду ждать вашего ответа. С наилучшими пожеланиями, Тейлор.",
